const form=document.querySelector(".contact-form");if(form&&form.dataset.enabled==="true"){const e=document.getElementById("form-status"),t=document.getElementById("form-error"),n=form.querySelector("button");form.addEventListener("submit",async s=>{if(s.preventDefault(),!form.reportValidity())return;n.disabled=!0,t.hidden=!0,e.textContent="Sending your enquiry…";const o=new AbortController,i=setTimeout(()=>o.abort(),15e3);try{const t=await fetch(form.action,{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:new URLSearchParams(new FormData(form)).toString(),signal:o.signal});if(!t.ok)throw new Error("Not accepted");e.textContent="Thank you. Your enquiry has been received.",e.focus(),form.reset()}catch{e.textContent="",t.textContent="We could not confirm delivery. Your message is still here. Check your connection before trying again; if the request timed out, it may already have arrived.",t.hidden=!1,t.focus()}finally{clearTimeout(i),n.disabled=!1}})}